// Package fixture builds deterministic synthetic MXF/MP4 inputs so tests and
// the CLI never depend on external media files.
package fixture

import (
	"bytes"
	"encoding/binary"

	"github.com/pion/rtp"
)

// Box construction helpers. The fixture writer deliberately implements just
// the ISO-BMFF subset the parser reads, so generated bytes stay inspectable.
func rawBox(typ string, parts ...[]byte) []byte {
	size := 8
	for _, p := range parts {
		size += len(p)
	}
	b := make([]byte, 0, size)
	b = binary.BigEndian.AppendUint32(b, uint32(size))
	b = append(b, typ...)
	for _, p := range parts {
		b = append(b, p...)
	}
	return b
}

func fullBox(typ string, version byte, flags uint32, parts ...[]byte) []byte {
	hdr := []byte{version, byte(flags >> 16), byte(flags >> 8), byte(flags)}
	return rawBox(typ, append([][]byte{hdr}, parts...)...)
}

func u16(v uint16) []byte { return binary.BigEndian.AppendUint16(nil, v) }
func u32(v uint32) []byte { return binary.BigEndian.AppendUint32(nil, v) }
func i32(v int32) []byte  { return u32(uint32(v)) }
func u64(v uint64) []byte { return binary.BigEndian.AppendUint64(nil, v) }

func cat(parts ...[]byte) []byte { return bytes.Join(parts, nil) }

func repeat(b byte, n int) []byte { return bytes.Repeat([]byte{b}, n) }

// matrixForRotation returns the 16.16/2.30 display matrix for a clockwise
// rotation in degrees.
func matrixForRotation(deg int) [9]int32 {
	const one = 1 << 16
	switch deg {
	case 90:
		return [9]int32{0, one, 0, -one, 0, 0, 0, 0, 1 << 30}
	case 180:
		return [9]int32{-one, 0, 0, 0, -one, 0, 0, 0, 1 << 30}
	case 270:
		return [9]int32{0, -one, 0, one, 0, 0, 0, 0, 1 << 30}
	default:
		return [9]int32{one, 0, 0, 0, one, 0, 0, 0, 1 << 30}
	}
}

func matrixBytes(m [9]int32) []byte {
	var b []byte
	for _, v := range m {
		b = append(b, i32(v)...)
	}
	return b
}

// colorBox is one colr payload.
type colorBox struct {
	typ       string // "nclx" or "prof"
	primaries uint16
	transfer  uint16
	matrix    uint16
	fullRange bool
	profile   []byte
}

func (c colorBox) bytes() []byte {
	if c.typ == "nclx" {
		var fr byte
		if c.fullRange {
			fr = 0x80
		}
		return rawBox("colr", []byte("nclx"), u16(c.primaries), u16(c.transfer), u16(c.matrix), []byte{fr})
	}
	return rawBox("colr", []byte(c.typ), c.profile)
}

// cropBox encodes a clap box. Numerators/denominators are passed explicitly so
// malformed fixtures can express impossible apertures.
type cropBox struct {
	wN, wD, hN, hD int32
	offXN, offXD   int32
	offYN, offYD   int32
}

func (c cropBox) bytes() []byte {
	return rawBox("clap",
		i32(c.wN), i32(c.wD), i32(c.hN), i32(c.hD),
		i32(c.offXN), i32(c.offXD), i32(c.offYN), i32(c.offYD))
}

// mp4Spec describes a two-track fixture: one video and one RTP-framed audio
// track. Audio sample payloads are entire RTP packets so the silence stage can
// validate sequence continuity with pion/rtp.
type mp4Spec struct {
	videoSamples   int
	videoTimescale uint32
	videoDelta     uint32
	videoSampleLen int
	audioPackets   int
	audioTimescale uint32
	audioDelta     uint32
	audioPayload   int
	rotation       int
	crop           *cropBox
	colors         []colorBox
	// audioAmplitude maps an audio packet index to a peak int16 amplitude.
	audioAmplitude func(i int) int16
	// videoSeed makes each video sample's bytes reproducible but distinct.
	videoSeed func(i int) byte
}

func defaultSpec() mp4Spec {
	return mp4Spec{
		videoSamples:   150,
		videoTimescale: 90000,
		videoDelta:     3000,
		videoSampleLen: 64,
		audioPackets:   235,
		audioTimescale: 48000,
		audioDelta:     1024,
		audioPayload:   160,
		rotation:       90,
		crop:           &cropBox{wN: 1904, wD: 1, hN: 1080, hD: 1, offXD: 1, offYD: 1},
		colors: []colorBox{
			{typ: "nclx", primaries: 1, transfer: 1, matrix: 1},
			{typ: "nclx", primaries: 9, transfer: 16, matrix: 9, fullRange: true},
		},
		audioAmplitude: func(i int) int16 {
			// 0-1.5s loud, 1.5-2.5s silent, then loud.
			ms := int64(i) * 1024 * 1000 / 48000
			if ms >= 1500 && ms < 2500 {
				return 0
			}
			return 2000
		},
		videoSeed: func(i int) byte { return byte(i * 7) },
	}
}

func (s mp4Spec) videoBytes(i int) []byte {
	b := make([]byte, s.videoSampleLen)
	for k := range b {
		b[k] = s.videoSeed(i) ^ byte(k*3)
	}
	return b
}

func (s mp4Spec) audioPacketsBytes() [][]byte {
	out := make([][]byte, s.audioPackets)
	for i := range out {
		amp := s.audioAmplitude(i)
		payload := make([]byte, s.audioPayload)
		for k := 0; k+1 < len(payload); k += 2 {
			// Alternating samples exercise signed amplitude, not just bytes.
			if k%4 == 0 {
				binary.LittleEndian.PutUint16(payload[k:], uint16(amp))
			} else {
				binary.LittleEndian.PutUint16(payload[k:], uint16(-amp))
			}
		}
		p := rtp.Packet{
			Header: rtp.Header{
				Version:        2,
				PayloadType:    111,
				SequenceNumber: uint16(i),
				Timestamp:      uint32(i) * s.audioDelta,
				SSRC:           0x0badcafe,
			},
			Payload: payload,
		}
		b, err := p.Marshal()
		if err != nil {
			panic(err)
		}
		out[i] = b
	}
	return out
}
